// Требование: let/const, массив, объект, цикл for, if/else

const studentName = "Пужук"; // Используем const
let grades = [4, 5, 3, 5, 4]; // Используем let и массив (Array)
let sum = 0;

// Используем цикл for
for (let i = 0; i < grades.length; i++) {
    sum += grades[i];
}

let average = sum / grades.length;
let status = "";

// Используем if/else
if (average >= 4) {
    status = "Молодец, стипендия будет!";
} else {
    status = "Нужно подтянуть хвосты...";
}

// Используем объект (Object)
const resultData = {
    name: studentName,
    marks: grades,
    averageScore: average,
    verdict: status,
    trigger: msg.payload // то самое слово "старт" из inject
};

// Функция должна возвращать объект с полем payload
msg.payload = resultData;
return msg;
